import { AuthSignIn } from "@/components/design-for-ai/auth-sign-in";

<AuthSignIn
  title="Sign in to Halyard"
  providers={["google", "github"]}
  onSubmit={async ({ email, password, remember }) => {
    const res = await fetch("/api/session", { method: "POST", body: JSON.stringify({ email, password, remember }) });
    if (res.status === 423) return { ok: false, reason: "locked", retryAfter: Number(res.headers.get("Retry-After") ?? 30) };
    if (!res.ok) return { ok: false, reason: "invalid_credentials", attemptsLeft: 2 };
    return { ok: true };
  }}
  onSso={(provider) => signIn(provider)}
  onSuccess={() => router.push("/app")}
/>
